import Foundation

/// Looks places up by id (#1992). It reads only what ships in the App and never goes to the network.
///
/// What it reads, in this order:
/// 1. `LioPlaces.v1.json`: the App's slim copy of the reviewed library, generated by `knowledge/places/generate.py`
///    (#1985). It is not in the App yet, so until it lands this step finds nothing.
/// 2. Debug builds only: `LioPlaceSamples.v1.json`, a handful of development samples in the library's shape, so the
///    page can be built and tried before the library exists. Release builds never read it, because its entries
///    are unreviewed and its coordinates are approximate.
///
/// A file may be `{"places": [...]}` (the slim copy, the library, the development pack) or a bare array. Entries
/// that cannot be read are skipped; the rest still load. The first entry with an id wins.
struct LioPlaceRepository: Sendable {
    /// A place and how far it is from another one, in metres.
    struct Neighbour: Equatable, Sendable {
        let place: LioPlace
        let metres: Double
    }

    let places: [LioPlace]
    private let index: [String: Int]

    init(places: [LioPlace]) {
        var index: [String: Int] = [:]
        var unique: [LioPlace] = []
        for place in places where index[place.id] == nil {
            index[place.id] = unique.count
            unique.append(place)
        }
        self.places = unique
        self.index = index
    }

    func place(id: String) -> LioPlace? {
        index[id].map { places[$0] }
    }

    /// Places of `category` within `maxMetres` of `place`, nearest first. A place with no coordinate has none.
    func nearby(_ place: LioPlace, category: LioPlace.Category, limit: Int, maxMetres: Double = 1_500) -> [Neighbour] {
        guard let origin = place.point, limit > 0 else { return [] }
        return places.compactMap { other -> Neighbour? in
            guard other.id != place.id, other.category == category, let point = other.point else { return nil }
            let metres = Self.metres(from: origin, to: point)
            return metres <= maxMetres ? Neighbour(place: other, metres: metres) : nil
        }
        .sorted { ($0.metres, $0.place.id) < ($1.metres, $1.place.id) }
        .prefix(limit).map { $0 }
    }

    /// Great-circle distance (haversine); good to a few metres at city scale, which is all the page needs.
    static func metres(from a: LioItinerary.Point, to b: LioItinerary.Point) -> Double {
        let radius = 6_371_000.0
        let (lat1, lat2) = (a.latitude * .pi / 180, b.latitude * .pi / 180)
        let (dLat, dLng) = (lat2 - lat1, (b.longitude - a.longitude) * .pi / 180)
        let h = sin(dLat / 2) * sin(dLat / 2) + cos(lat1) * cos(lat2) * sin(dLng / 2) * sin(dLng / 2)
        return 2 * radius * asin(min(1, h.squareRoot()))
    }

    // MARK: Loading

    private struct Document: Decodable {
        let places: [Lossy<LioPlace>]
    }

    /// The places in `data`, skipping entries that cannot be read; empty when `data` is not a place file.
    static func places(in data: Data) -> [LioPlace] {
        let decoder = JSONDecoder()
        if let document = try? decoder.decode(Document.self, from: data) { return document.places.compactMap(\.value) }
        if let bare = try? decoder.decode([Lossy<LioPlace>].self, from: data) { return bare.compactMap(\.value) }
        return []
    }

    init(data: Data) {
        self.init(places: Self.places(in: data))
    }

    static let libraryResource = "LioPlaces.v1"
    static let sampleResource = "LioPlaceSamples.v1"

    /// The development samples in every build; `bundled` includes them in Debug builds only.
    static let samples = LioPlaceRepository(places: resource(sampleResource).map { places(in: $0) } ?? [])

    /// The repository this build shows (see the type's comment).
    static let bundled: LioPlaceRepository = {
        var places: [LioPlace] = []
        if let data = resource(libraryResource) { places += Self.places(in: data) }
        #if DEBUG
        if let data = resource(sampleResource) { places += Self.places(in: data) }
        #endif
        return LioPlaceRepository(places: places)
    }()

    static func resource(_ name: String) -> Data? {
        Bundle.module.url(forResource: name, withExtension: "json").flatMap { try? Data(contentsOf: $0) }
    }
}
